import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { tablesApi } from '../utils/api';
import toast from 'react-hot-toast';
import OrderModal from './OrderModal';
import BillModal from './BillModal';

const STATE_META = {
  free:          { label: 'Bo\'sh',         color: 'text-emerald-400', bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', dot: 'bg-emerald-400' },
  reserved:      { label: 'Band',           color: 'text-blue-400',    bg: 'bg-blue-500/10',    border: 'border-blue-500/30',    dot: 'bg-blue-400' },
  occupied:      { label: 'Egallangan',     color: 'text-amber-400',   bg: 'bg-amber-500/10',   border: 'border-amber-500/30',   dot: 'bg-amber-400' },
  awaiting_bill: { label: 'Hisob kutmoqda', color: 'text-purple-400',  bg: 'bg-purple-500/10',  border: 'border-purple-500/30',  dot: 'bg-purple-400' },
  cleared:       { label: 'Tozalangan',     color: 'text-gray-400',    bg: 'bg-gray-500/10',    border: 'border-gray-700',       dot: 'bg-gray-500' },
};

export default function TablesView() {
  const { tables, staff, refreshTables, refreshKitchen } = useApp();
  const [seatModal, setSeatModal] = useState(null);
  const [orderModal, setOrderModal] = useState(null);
  const [billModal, setBillModal] = useState(null);
  const [customerName, setCustomerName] = useState('');
  const [selectedStaff, setSelectedStaff] = useState('');

  const waiters = staff.filter((s) => ['waiter', 'manager'].includes(s.role));

  const stats = {
    free: tables.filter((t) => t.state === 'free').length,
    occupied: tables.filter((t) => t.state === 'occupied').length,
    awaiting: tables.filter((t) => t.state === 'awaiting_bill').length,
  };

  async function handleSeat(table) {
    if (!customerName.trim()) { toast.error('Mijoz ismini kiriting'); return; }
    if (!selectedStaff) { toast.error('Xodimni tanlang'); return; }
    try {
      await tablesApi.seat(table.id, customerName.trim());
      await refreshTables();
      setSeatModal(null);
      setCustomerName('');
      toast.success(`${table.id}-stol egallandi`);
    } catch (err) {
      toast.error(err.response?.data?.error || 'Xatolik yuz berdi');
    }
  }

  async function handleClear(tableId) {
    try {
      await tablesApi.clear(tableId);
      await refreshTables();
      toast.success(`${tableId}-stol tozalandi`);
    } catch {
      toast.error('Tozalashda xatolik');
    }
  }

  return (
    <div className="space-y-6">
      {/* Stats row */}
      <div className="grid grid-cols-3 gap-4">
        <StatCard icon="🟢" label="Bo'sh stollar" value={stats.free} sub={`/ ${tables.length} jami`} color="emerald" />
        <StatCard icon="🟡" label="Egallangan" value={stats.occupied} sub="mijoz bilan" color="amber" />
        <StatCard icon="🟣" label="Hisob kutmoqda" value={stats.awaiting} sub="to'lov kerak" color="purple" />
      </div>

      {/* Tables grid */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        {tables.map((table) => {
          const meta = STATE_META[table.state] || STATE_META.free;
          return (
            <div key={table.id} className={`card border ${meta.border} p-5 transition-all hover:scale-[1.01]`}>
              {/* Header */}
              <div className="flex justify-between items-start mb-4">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="text-xl font-bold text-white">{table.id}-Stol</span>
                    <div className={`w-2 h-2 rounded-full ${meta.dot}`} />
                  </div>
                  <p className="text-xs text-gray-600 mt-0.5">{table.capacity} kishi sig'adi</p>
                </div>
                <span className={`badge ${meta.bg} ${meta.color} border ${meta.border}`}>
                  {meta.label}
                </span>
              </div>

              {/* Guest info */}
              {table.customerName && (
                <div className="mb-4 px-3 py-2 bg-white/5 rounded-lg">
                  <p className="text-xs text-gray-500">Mijoz</p>
                  <p className="text-sm text-white font-medium">{table.customerName}</p>
                </div>
              )}

              {/* Actions */}
              <div className="flex flex-wrap gap-2">
                {table.state === 'free' && (
                  <button onClick={() => { setSeatModal(table); setSelectedStaff(waiters[0]?.id || ''); }}
                    className="btn btn-sm btn-success w-full">
                    Mijoz o'tqazish
                  </button>
                )}
                {table.state === 'occupied' && (
                  <>
                    <button onClick={() => setOrderModal(table)} className="btn btn-sm btn-warning flex-1">
                      Buyurtma berish
                    </button>
                    <button onClick={() => setBillModal(table)} className="btn btn-sm btn-primary flex-1">
                      Hisob-kitob
                    </button>
                  </>
                )}
                {['occupied', 'awaiting_bill', 'cleared'].includes(table.state) && (
                  <button onClick={() => handleClear(table.id)} className="btn btn-sm btn-ghost w-full mt-1">
                    Stolni tozalash
                  </button>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Seat modal */}
      {seatModal && (
        <div className="modal-backdrop" onClick={() => setSeatModal(null)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center gap-3 mb-6">
              <div className="w-10 h-10 rounded-xl bg-emerald-500/20 flex items-center justify-center text-emerald-400 text-xl">🪑</div>
              <div>
                <h3 className="text-white font-bold text-lg">Mijoz o'tqazish</h3>
                <p className="text-gray-500 text-sm">{seatModal.id}-stol</p>
              </div>
            </div>

            <div className="space-y-4">
              <div>
                <label className="label">Mijoz ismi</label>
                <input className="input" placeholder="Masalan: Ahmadov Jasur"
                  value={customerName} onChange={(e) => setCustomerName(e.target.value)}
                  maxLength={80} autoFocus />
              </div>
              <div>
                <label className="label">Xizmat ko'rsatuvchi</label>
                <select className="input" value={selectedStaff} onChange={(e) => setSelectedStaff(e.target.value)}>
                  <option value="">Tanlang...</option>
                  {waiters.map((s) => (
                    <option key={s.id} value={s.id}>{s.name} — {s.role === 'manager' ? 'Menejer' : 'Ofitsiant'}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="flex gap-3 mt-6">
              <button onClick={() => handleSeat(seatModal)} className="btn btn-success flex-1">Tasdiqlash</button>
              <button onClick={() => setSeatModal(null)} className="btn btn-ghost flex-1">Bekor qilish</button>
            </div>
          </div>
        </div>
      )}

      {orderModal && (
        <OrderModal table={orderModal} staffId={selectedStaff || waiters[0]?.id}
          onClose={() => { setOrderModal(null); refreshTables(); refreshKitchen(); }} />
      )}
      {billModal && (
        <BillModal table={billModal} onClose={() => { setBillModal(null); refreshTables(); }} />
      )}
    </div>
  );
}

function StatCard({ icon, label, value, sub, color }) {
  const colors = {
    emerald: 'border-emerald-500/20 text-emerald-400',
    amber:   'border-amber-500/20 text-amber-400',
    purple:  'border-purple-500/20 text-purple-400',
  };
  return (
    <div className={`card border ${colors[color]} p-5`}>
      <div className="flex justify-between items-start">
        <div>
          <p className="text-gray-500 text-xs font-medium">{label}</p>
          <p className={`text-3xl font-bold mt-1 ${colors[color].split(' ')[1]}`}>{value}</p>
          <p className="text-gray-600 text-xs mt-1">{sub}</p>
        </div>
        <span className="text-2xl">{icon}</span>
      </div>
    </div>
  );
}
